const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function inventory(root) {
  const out = [];
  (function walk(dir) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const p = path.join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.isFile()) {
        const buf = fs.readFileSync(p);
        out.push({
          path: path.relative(root, p),
          bytes: buf.length,
          sha256: crypto.createHash('sha256').update(buf).digest('hex'),
        });
      }
    }
  })(root);
  return out;
}

const [a, b] = process.argv.slice(2);
const invA = inventory(a);
const invB = inventory(b);
const mapA = new Map(invA.map((f) => [f.path, f]));
const mapB = new Map(invB.map((f) => [f.path, f]));
const onlyInA = invA.filter((f) => !mapB.has(f.path)).map((f) => f.path);
const onlyInB = invB.filter((f) => !mapA.has(f.path)).map((f) => f.path);
const differing = invA
  .filter((f) => mapB.has(f.path) && mapB.get(f.path).sha256 !== f.sha256)
  .map((f) => ({ path: f.path, aBytes: f.bytes, bBytes: mapB.get(f.path).bytes, aSha256: f.sha256, bSha256: mapB.get(f.path).sha256 }));

const result = {
  runA: { dirLabel: path.basename(a), files: invA.length, totalBytes: invA.reduce((s, f) => s + f.bytes, 0), entries: invA },
  runB: { dirLabel: path.basename(b), files: invB.length, totalBytes: invB.reduce((s, f) => s + f.bytes, 0), entries: invB },
  comparison: { byteIdentical: onlyInA.length === 0 && onlyInB.length === 0 && differing.length === 0, onlyInRunA: onlyInA, onlyInRunB: onlyInB, differingContent: differing },
};
process.stdout.write(JSON.stringify(result, null, 2));

